class SimpleStack<T> {
    private ArrayList<T> items = new ArrayList<>();

    boolean isEmpty() {
        return items.isEmpty();
    }

    void push(T item) {
        items.add(item);
    }

    T pop() {
        if (isEmpty()) return null;
        return items.remove(items.size() - 1);
    }

    T peek() {
        if (isEmpty()) return null;
        return items.get(items.size() - 1);
    }

    int size() {
        return items.size();
    }
}

